import 'package:flutter_test/flutter_test.dart';
import 'package:sqflite/sqflite.dart';
import 'package:salonmanager/core/database/salon_database.dart';
import 'package:salonmanager/core/repositories/sqlite_cashier_shift_repository.dart';
void main(){TestWidgetsFlutterBinding.ensureInitialized();setUp(()async=>SalonDatabase.instance.close());tearDown(()async=>SalonDatabase.instance.close());
test('cashier shift reconciles expected cash and variance',()async{final db=await SalonDatabase.instance.database;final repo=SqliteCashierShiftRepository(SalonDatabase.instance);await repo.openShift(openingCash:100000);final now=DateTime.now();await db.insert('customers',{'id':'cash-customer','full_name':'Cash Customer','phone':'0900','created_at':now.toIso8601String(),'updated_at':now.toIso8601String()},conflictAlgorithm:ConflictAlgorithm.abort);await db.insert('invoices',{'id':'cash-invoice','customer_id':'cash-customer','subtotal':200000,'discount_amount':0,'total_amount':200000,'payment_method':'Tiền mặt','paid_at':now.toIso8601String(),'created_at':now.toIso8601String(),'updated_at':now.toIso8601String()});await repo.recordCashMovement(type:'in',amount:50000,reason:'Bổ sung quỹ');await repo.recordCashMovement(type:'out',amount:30000,reason:'Mua vật tư');final live=await repo.fetchOpenShift();expect(live!.liveExpectedCash,320000);final closed=await repo.closeShift(countedCash:315000);expect(closed.expectedCash,320000);expect(closed.variance,-5000);expect(await repo.fetchOpenShift(),isNull);});
test('only one shift can be open',()async{final repo=SqliteCashierShiftRepository(SalonDatabase.instance);await repo.openShift(openingCash:0);await expectLater(repo.openShift(openingCash:0),throwsStateError);});}
